	-- (1.8.0) the inns, one stamp
	["Loyalty: one stamp here. %s at %d."] = "Treue: 1 Stempel hier. %s ab %d.",
	["1 stamp"] = "1 Stempel",
	-- (1.8.0) the inns: the tour of the album, the command
	["Talk to the innkeepers: a stamp a day on your loyalty card, a visa for each inn in your travel passport, and the loyalty of each innkeeper. Seven stamps make a booster."] = "Sprich mit den Gastwirten: ein Stempel pro Tag auf deiner Treuekarte, ein Visum pro Gasthaus in deinem Reisepass und die Treue jedes Gastwirts. Sieben Stempel ergeben einen Booster.",
	["/curator inns: your loyalty card and your travel passport"] = "/curator inns: deine Treuekarte und dein Reisepass",
	-- (1.8.0) the life of the inns: the rumors, the innkeeper's bet, the home inn, the evening at the inn, the toasts
	["%s is yours."] = "%s gehört dir.",
	["%s raises a glass to you!"] = "%s erhebt das Glas auf dich!",
	["%s: %d copies to spare (one copy always stays in your album)."] = "%s: %d Exemplare übrig (ein Exemplar bleibt immer in deinem Album).",
	["(Its card is twice as easy to find today.)"] = "(Seine Karte ist heute doppelt so leicht zu finden.)",
	["10 rumors heard from the innkeepers."] = "10 Gerüchte von den Gastwirten gehört.",
	["A bet is a bet! Come back tomorrow for another."] = "Wette ist Wette! Komm morgen für die nächste wieder.",
	["A stamp more on your loyalty card."] = "Ein Stempel mehr auf deiner Treuekarte.",
	["Another card"] = "Andere Karte",
	["Any rumors?"] = "Gibt es Gerüchte?",
	["Bet one of your duplicates: I put three cards of my album face down, two of its rarity and one of the rarity above. Pick one, it is yours!"] = "Setz eine deiner doppelten Karten: Ich lege drei Karten aus meinem Album verdeckt hin, zwei ihrer Seltenheit und eine der Seltenheit darüber. Zieh eine, sie gehört dir!",
	["Bet this card"] = "Diese Karte setzen",
	["Cheers with %s!"] = "Prost mit %s!",
	["Cheers!"] = "Prost!",
	["Duplicates to bet: %d"] = "Doppelte zum Setzen: %d",
	["Evening at the inn: double stamp tonight!"] = "Abend im Gasthaus: heute Abend doppelter Stempel!",
	["Evening at the inn: double stamp!"] = "Abend im Gasthaus: doppelter Stempel!",
	["Friday Night"] = "Freitagabend",
	["From an innkeeper"] = "Von einem Gastwirt",
	["From the album: %s"] = "Aus dem Album: %s",
	["I keep my rumors for my regulars. Come back and see me: at %d stamps here, I will tell you what I hear."] = "Meine Gerüchte erzähle ich nur Stammkunden. Komm wieder: Ab %d Stempeln hier erzähle ich dir, was ich höre.",
	["Jackpot! %s is yours."] = "Volltreffer! %s gehört dir.",
	["No duplicate of this rarity."] = "Keine doppelte Karte dieser Seltenheit.",
	["Nothing new around here today."] = "Heute gibt es hier nichts Neues.",
	["One bet a day! Come back tomorrow."] = "Eine Wette pro Tag! Komm morgen wieder.",
