	["A step of a quest objective"] = "任务目标的一个步骤",
	["Booster bar"] = "补充包进度条",
	["Booster bar hidden (/curator bar to show it)."] = "补充包进度条已隐藏（输入 /curator bar 显示）。",
	["Booster bar shown."] = "补充包进度条已显示。",
	["Booster bar: %d%%"] = "补充包进度条：%d%%",
