ns.LocaleTables = T

local function Pick(locale)
	local t = T[locale]
	ns.L = setmetatable({}, {
		__index = function(_, key)
			return (t and t[key]) or key
		end,
	})
	ns.locale = locale
end
ns.SetLocale = Pick
Pick(GetLocale())
